/**
 * Mencari bentuk asal (lemma) bagi perkataan yang ditekan di dalam subtitle.
 */
export function findBaseForm(word: string): BaseFormInfo | null {
  if (!word) return null;
  const clean = word.toLowerCase().trim();
  return baseFormDictionary[clean] || null;
}
